<?php require dirname(__DIR__).'/includes/bootstrap.php';require APP_ROOT.'/services/chat.php';$u=require_role(['KHACH_HANG','NHAN_VIEN','ADMIN']);$id=(int)get('id');conversation($id,$u);$after=max(0,(int)get('after'));session_write_close();$rows=db_all('SELECT n.*,t.ho_ten FROM tin_nhan n JOIN tai_khoan t ON t.id=n.nguoi_gui_id WHERE n.ma_hoi_thoai=? AND n.ma_tin_nhan>? ORDER BY n.ma_tin_nhan LIMIT 100',[$id,$after]);foreach($rows as&$r){$r['files']=db_all('SELECT id,ten_goc FROM tep_tin_nhan WHERE ma_tin_nhan=?',[$r['ma_tin_nhan']]);foreach($r['files']as&$f)$f['url']=url('api/tai_tep.php?id='.$f['id']);}json_response(['items'=>$rows]);
